package br.com.sergio.gestaopedidos.repository;
import br.com.sergio.gestaopedidos.entity.ComposicaoProduto;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;
public interface ComposicaoProdutoRepository extends JpaRepository<ComposicaoProduto,Long>{boolean existsByProdutoComercialId(Long id);Optional<ComposicaoProduto> findByProdutoComercialId(Long id);@EntityGraph(attributePaths={"produtoComercial","itens","itens.insumo","itens.preparacao"})Optional<ComposicaoProduto> findDetailedByProdutoComercialId(Long id);@EntityGraph(attributePaths={"produtoComercial","itens","itens.insumo","itens.preparacao"})@Query("SELECT DISTINCT c FROM ComposicaoProduto c WHERE c.id=:id")Optional<ComposicaoProduto> buscarDetalhada(@Param("id")Long id);@Query("SELECT c FROM ComposicaoProduto c JOIN c.produtoComercial p WHERE (:nome='' OR LOWER(p.nome) LIKE LOWER(CONCAT('%',:nome,'%'))) AND (:ativa IS NULL OR c.ativa=:ativa)")Page<ComposicaoProduto> listar(@Param("nome")String nome,@Param("ativa")Boolean ativa,Pageable pageable);}
